#!/usr/bin/env bash
# write-image-values.sh <output file> <image tag> <environment>
#
# Writes a Helm values file that points every Vigil component at the CI-built images
#   ghcr.io/<owner>/vigil-core|vigil-worker|vigil-frontend:<tag>
# Used by ci.yaml (bump-dev -> values-dev-images.yaml) and promote.yaml
# (-> values-prod-images.yaml). OWNER defaults to the repository owner, lower-cased
# (container registry names must be lower case).
set -euo pipefail

out="$1"
tag="$2"
env="$3"
owner="$(echo "${OWNER:-${GITHUB_REPOSITORY_OWNER:?}}" | tr '[:upper:]' '[:lower:]')"

# Only allow tags that look like "sha-<hex>" so nothing odd can be written into YAML.
if ! [[ "$tag" =~ ^sha-[0-9a-f]{7,40}$ ]]; then
  echo "refusing unexpected image tag: $tag" >&2
  exit 1
fi

img() { # $1 = repository name
  printf '  image:\n    registry: ghcr.io\n    repository: %s/%s\n    tag: "%s"\n    pullPolicy: IfNotPresent\n' \
    "$owner" "$1" "$tag"
}

{
  echo "# values-${env}-images.yaml - which IMAGES the ${env} environment runs."
  echo "# GENERATED by .github/scripts/write-image-values.sh - do not edit by hand."
  echo "# Images built by CI from commit ${tag#sha-}."
  echo "api:";      img vigil-core
  echo "notifier:"; img vigil-core
  echo "demoShop:"; img vigil-core
  echo "worker:";   img vigil-worker
  echo "frontend:"; img vigil-frontend
} > "$out"

cat "$out"
